/**
 * Live Keys: a session keyboard player, built like the Live Drummer. Every bar is generated by
 * the pure genKeysBar() below, so the live player and "print to timeline" always play the same notes.
 *
 * Chords are written as roman numerals in the style's key (I = tonic). Upper case is major,
 * lower case minor; a suffix sets the quality (7, maj7, 9, maj9, 11, 13, 6, 69, sus, 7sus, sus2,
 * 5, add9, ø, °, °7, 7#9, 7b9, +). Bars are separated by spaces; "ii7,V7" splits a bar in half.
 *
 * Rhythm strings are one 4/4 bar of 16ths.
 *   Right hand: X accent, x normal, o soft, g ghost (whole chord) · a arpeggio note · t top note
 *               · - holds the previous note · . rest
 *   Left hand:  X x o g root · 3 third · 5 fifth · 6 sixth · 7 seventh · 8 octave · c mid chord
 *               (stride) · - hold · . rest. "walk" plays a walking bass line instead.
 * Each hand has a base line (always played) and an optional busy line that fades in as the
 * Simple ↔ Complex control goes up.
 */

import { applyPreset } from "./presets";
import type { SynthPatch } from "./types";

export type KeysGroup = "Jazz" | "Rock" | "Blues & Gospel" | "Hip-Hop & R&B" | "Electronic" | "Pop & Country" | "World & Latin";
export type KeysSoundId = "grand" | "rhodes" | "wurli" | "organ" | "clav" | "deep" | "strings" | "pad" | "synth";
export type Voicing = "triad" | "seventh" | "rootless" | "power" | "stab" | "spread";
export type KeysFill = "run" | "cascade" | "stabs" | "turn" | "gliss";
export type KeysLook = "grand" | "ep" | "wurli" | "organ" | "clav" | "synth";

export interface KeysSound { id: KeysSoundId; label: string; preset: string; look: KeysLook; sustained?: boolean }
export const KEYS_SOUNDS: KeysSound[] = [
  { id: "grand", label: "Grand Piano", preset: "Grand-ish Piano", look: "grand" },
  { id: "rhodes", label: "Electric Piano", preset: "Rhodes Soul", look: "ep" },
  { id: "wurli", label: "Wurlitzer", preset: "Wurli Warm", look: "wurli" },
  { id: "organ", label: "Drawbar Organ", preset: "Organ Drawbar", look: "organ", sustained: true },
  { id: "clav", label: "Clavinet", preset: "Clav Funk", look: "clav" },
  { id: "deep", label: "Deep House Keys", preset: "Deep Keys", look: "synth" },
  { id: "strings", label: "String Machine", preset: "Prophet Strings", look: "synth", sustained: true },
  { id: "pad", label: "Warm Pad", preset: "Warehouse Pad", look: "synth", sustained: true },
  { id: "synth", label: "Poly Synth", preset: "Poly Synth Keys", look: "synth" },
];
export const soundById = (id: string) => KEYS_SOUNDS.find((s) => s.id === id) ?? KEYS_SOUNDS[0]!;

/**
 * The instrument patch for a keyboard sound: the factory preset, played polyphonically with the
 * arpeggiator off (the player writes its own notes) and one voice per key for pianos so chords stay clean.
 */
export function keysPatch(id: KeysSoundId): SynthPatch {
  const s = soundById(id);
  const p = applyPreset(s.preset);
  p.arp = { ...p.arp, on: false };
  p.voiceMode = "poly";
  p.glide = 0;
  if (!s.sustained && s.id !== "synth") p.unison = { ...p.unison, voices: 1, detune: 0, width: 0 };
  p.fx = { ...p.fx, distortion: s.id === "clav" ? Math.min(p.fx.distortion, 0.12) : 0, saturation: 0, bitcrush: 0, flanger: 0, phaser: 0, delay: 0 };
  // Headroom: the session player stacks chords, bass and runs (up to ~10 keys at once), so each
  // key gets a fixed, quiet level instead of a lead-synth level. No drive, and a clean voice path
  // (no saturation stage) except the clavinet's small bite, so full chords never fold over or clip.
  // No per-key echo/flanger/phaser either: every key would build its own effect nodes, and a busy
  // style plays hundreds of keys a minute (that overload is what made dense styles crackle or drop
  // out). Space comes from the shared chorus/reverb sends and the channel's FX rack instead.
  p.drive = 0;
  p.clean = s.id !== "clav";
  p.lightVoices = true;
  p.resonance = Math.min(p.resonance, 2);
  // Gentler velocity response, so soft comping stays audible while accents still lift.
  p.velocitySens = 0.6;
  // Pads and strings speak quickly enough to be heard on a chord change, and their tails don't
  // pile up dozens of voices.
  if (s.sustained) p.amp = { ...p.amp, attack: Math.min(p.amp.attack, 0.25), release: Math.min(p.amp.release, 1.2) };
  const on = p.oscillators.filter((o) => o.on);
  const sum = on.reduce((t, o) => t + o.level, 0) || 1;
  const scale = (KEYS_VOICE_LEVEL[s.id] ?? 0.3) / sum;
  p.oscillators = p.oscillators.map((o) => ({ ...o, level: Math.round(o.level * scale * 1000) / 1000 }));
  return p;
}

/** Bump when keysPatch's levels change, so Live Keys tracks made earlier pick up the new sound. */
export const KEYS_PATCH_REV = 4;

/** Summed oscillator level per key for each sound (bright/sustained sounds sit lower). */
const KEYS_VOICE_LEVEL: Partial<Record<KeysSoundId, number>> = {
  grand: 0.42, rhodes: 0.42, wurli: 0.42, organ: 0.4, clav: 0.16, deep: 0.42, strings: 0.45, pad: 0.45, synth: 0.36,
};

export interface KeysStyle {
  id: string;
  label: string;
  group: KeysGroup;
  bpm: number;
  /** suggested song swing 0..0.6 */
  swing: number;
  sound: KeysSoundId;
  /** default key, 0 = C … 11 = B */
  tonic: number;
  prog: string;
  voicing: Voicing;
  fill: KeysFill;
  right: [string, string?];
  left: [string, string?] | "walk";
}

const k = (id: string, label: string, group: KeysGroup, bpm: number, swing: number, sound: KeysSoundId, tonic: number, prog: string, voicing: Voicing, fill: KeysFill, right: KeysStyle["right"], left: KeysStyle["left"]): KeysStyle =>
  ({ id, label, group, bpm, swing, sound, tonic, prog, voicing, fill, right, left });

