// ---------------------------------------------------------------- chords

export interface Chord { root: number; intervals: number[]; symbol: string; quality: string }

const DEGREE: Record<string, number> = { I: 0, II: 2, III: 4, IV: 5, V: 7, VI: 9, VII: 11 };
const MAJOR_Q: Record<string, number[]> = {
  "": [0, 4, 7], "7": [0, 4, 7, 10], maj7: [0, 4, 7, 11], "9": [0, 4, 7, 10, 14], maj9: [0, 4, 7, 11, 14], "11": [0, 7, 10, 14, 17],
  "13": [0, 4, 7, 10, 14, 21], "6": [0, 4, 7, 9], "69": [0, 4, 7, 9, 14], add9: [0, 4, 7, 14], "7#9": [0, 4, 7, 10, 15], "7b9": [0, 4, 7, 10, 13], "+": [0, 4, 8],
};
const MINOR_Q: Record<string, number[]> = {
  "": [0, 3, 7], "7": [0, 3, 7, 10], maj7: [0, 3, 7, 11], "9": [0, 3, 7, 10, 14], "11": [0, 3, 7, 10, 14, 17], "13": [0, 3, 7, 10, 14, 21],
  "6": [0, 3, 7, 9], add9: [0, 3, 7, 14],
};
const ANY_Q: Record<string, number[]> = {
  sus: [0, 5, 7], sus4: [0, 5, 7], sus2: [0, 2, 7], "7sus": [0, 5, 7, 10], "5": [0, 7], "ø": [0, 3, 6, 10], m7b5: [0, 3, 6, 10], "°": [0, 3, 6], dim: [0, 3, 6], "°7": [0, 3, 6, 9],
};
const SHOWN: Record<string, string> = { "ø": "m7♭5", m7b5: "m7♭5", "°": "dim", dim: "dim", "°7": "dim7", "7#9": "7♯9", "7b9": "7♭9", "+": "aug", "7sus": "7sus4", sus: "sus4" };

/** Parses one roman-numeral chord, e.g. "bVImaj7" or "ii9". Returns null for anything it can't read. */
export function parseChord(token: string): Chord | null {
  const m = /^([b#]?)(VII|VI|V|IV|III|II|I|vii|vi|v|iv|iii|ii|i)(.*)$/.exec(token.trim());
  if (!m) return null;
  const [, acc = "", numeral = "", suffix = ""] = m;
  const minor = numeral === numeral.toLowerCase();
  const root = (((DEGREE[numeral.toUpperCase()] ?? 0) + (acc === "b" ? -1 : acc === "#" ? 1 : 0)) % 12 + 12) % 12;
  const intervals = ANY_Q[suffix] ?? (minor ? MINOR_Q[suffix] : MAJOR_Q[suffix]);
  if (!intervals) return null;
  const quality = ANY_Q[suffix] ? (SHOWN[suffix] ?? suffix) : minor ? `m${suffix === "maj7" ? "(maj7)" : suffix}` : (SHOWN[suffix] ?? suffix);
  return { root, intervals: [...intervals], symbol: token.trim(), quality };
}

/** The progression as bars, each bar a list of one or two chords. */
export function parseProgression(prog: string): Chord[][] {
  const bars = prog.trim().split(/\s+/).filter(Boolean).map((bar) => bar.split(",").map(parseChord).filter((c): c is Chord => !!c));
  const ok = bars.filter((b) => b.length);
  return ok.length ? ok : [[parseChord("I")!]];
}

const progCache = new Map<string, Chord[][]>();
function progressionOf(settings: KeysSettings): Chord[][] {
  const text = KEYS_PROGRESSIONS.find((p) => p.id === settings.prog)?.prog ?? keysStyleById(settings.style).prog;
  let bars = progCache.get(text);
  if (!bars) { bars = parseProgression(text); progCache.set(text, bars); }
  return bars;
}

/** The chord playing at a step of a bar (bars with two chords change half-way). */
export function chordAt(settings: KeysSettings, bar: number, step: number, stepsPerBar = 16): Chord {
  const bars = progressionOf(settings);
  const chords = bars[((bar % bars.length) + bars.length) % bars.length]!;
  if (chords.length === 1) return chords[0]!;
  const i = Math.min(chords.length - 1, Math.floor((step / Math.max(1, stepsPerBar)) * chords.length));
  return chords[i]!;
}

/** Chord symbol in the chosen key, e.g. "Dm7" or "B♭maj7". */
export function chordName(settings: KeysSettings, chord: Chord): string {
  return `${NOTE_NAMES[(settings.tonic + chord.root) % 12]}${chord.quality}`;
}

// ---------------------------------------------------------------- settings

export interface KeysSettings {
  style: string;
  /** key, 0 = C … 11 = B */
  tonic: number;
  /** "" = the style's own chords, otherwise a KEYS_PROGRESSIONS id */
  prog: string;
  sound: KeysSoundId;
  /** KEYS_PATCH_REV the track's sound was built with (missing = before the headroom fix) */
  patchRev?: number;
  /** 0 simple … 1 complex */
  complexity: number;
  /** 0 soft … 1 loud */
  loudness: number;
  /** 0 no fills … 1 fills every 2 bars */
  fills: number;
  /** 0 robotic … 1 loose (velocity feel only, so live and printed parts match) */
  humanize: number;
  /** right-hand register: -1 low, 0 middle, 1 high */
  range: number;
  hands: { left: boolean; right: boolean };
  /** variation seed — "New variation" changes it */
  seed: number;
}

export const defaultKeys = (styleId = "medium-swing"): KeysSettings => {
  const s = keysStyleById(styleId);
  return { style: s.id, tonic: s.tonic, prog: "", sound: s.sound, patchRev: KEYS_PATCH_REV, complexity: 0.45, loudness: 0.6, fills: 0.5, humanize: 0.35, range: 0, hands: { left: true, right: true }, seed: 1 };
};

export type Hand = "L" | "R";
export interface KeyNote { pitch: number; step: number; length: number; vel: number; hand: Hand }
export interface KeysBarOptions { fill?: boolean; hit?: boolean; silent?: boolean }

/** Small deterministic hash → 0..1, so a bar always generates the same way. */
export function rand01(...parts: (number | string)[]): number {
  let h = 2166136261;
  for (const p of parts) {
    const s = String(p);
    for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
    h = Math.imul(h ^ 0x9e37, 16777619);
  }
  h ^= h >>> 13; h = Math.imul(h, 0x5bd1e995); h ^= h >>> 15;
  return (h >>> 0) / 4294967296;
}

export function fillEvery(fills: number): number {
  if (fills <= 0.02) return 0;
  if (fills <= 0.4) return 8;
  if (fills <= 0.75) return 4;
  return 2;
}
export const isFillBar = (bar: number, fills: number) => { const n = fillEvery(fills); return n > 0 && (bar + 1) % n === 0; };
/** A big chord on the first bar and on the downbeat after each fill. */
export function keysBarOptions(settings: KeysSettings, bar: number): KeysBarOptions {
  const n = fillEvery(settings.fills);
  return { fill: isFillBar(bar, settings.fills), hit: bar === 0 || (n > 0 && bar % n === 0) };
}

// ---------------------------------------------------------------- voicing

const VEL: Record<string, number> = { X: 1, x: 0.82, o: 0.6, g: 0.34, a: 0.7, t: 0.76 };
const LEFT_VEL: Record<string, number> = { X: 1, x: 0.82, o: 0.6, g: 0.34, "3": 0.72, "5": 0.76, "6": 0.72, "7": 0.72, "8": 0.72, c: 0.66 };

/** Chord extensions follow the Simple ↔ Complex control: plain at the bottom, added 9ths at the top. */
function shaped(chord: Chord, cx: number): number[] {
  let iv = chord.intervals;
  if (cx < 0.22) iv = iv.filter((i) => i < 12 || iv.length <= 3);
  const hasSeventh = iv.some((i) => i === 10 || i === 11);
  const dim = iv.includes(6) && iv.includes(3);
  if (cx > 0.62 && hasSeventh && !dim && !iv.some((i) => i > 12)) iv = [...iv, 14];
  return iv;
}

/** Closed voicing nearest the centre pitch (smooth voice leading from chord to chord). */
function closed(rootPc: number, offs: number[], center: number): number[] {
  const pcs: number[] = [];
  for (const o of offs) { const pc = (((o % 12) + 12) % 12); if (!pcs.includes(pc)) pcs.push(pc); }
  let best: number[] = [];
  let bestScore = Infinity;
  for (let r = 0; r < pcs.length; r++) {
    const order = [...pcs.slice(r), ...pcs.slice(0, r)];
    const stack: number[] = [];
    for (const pc of order) {
      let p = rootPc + pc;
      while (stack.length && p <= stack[stack.length - 1]!) p += 12;
      stack.push(p);
    }
    const mean = stack.reduce((a, b) => a + b, 0) / stack.length;
    const shift = Math.round((center - mean) / 12) * 12;
    const placed = stack.map((p) => p + shift);
    const score = Math.abs(placed.reduce((a, b) => a + b, 0) / placed.length - center);
    if (score < bestScore - 1e-6) { bestScore = score; best = placed; }
  }
  return best;
}

/** The right hand's notes for a chord. */
export function voiceChord(settings: KeysSettings, chord: Chord, voicing: Voicing): number[] {
  const rootPc = (settings.tonic + chord.root) % 12;
  const center = 64 + Math.max(-1, Math.min(1, Math.round(settings.range))) * 9;
  const iv = shaped(chord, settings.complexity);
  const third = iv.find((i) => i === 3 || i === 4) ?? iv.find((i) => i === 2 || i === 5) ?? 4;
  const fifth = iv.find((i) => i >= 6 && i <= 8) ?? 7;
  const seventh = iv.find((i) => i === 9 || i === 10 || i === 11);
  const triad = [0, third, fifth];
  let out: number[];
  switch (voicing) {
    case "triad": out = closed(rootPc, triad, center); break;
    case "seventh": out = closed(rootPc, seventh != null ? [0, third, fifth, seventh, ...(iv.includes(14) ? [14] : [])] : triad, center); break;
    case "rootless": {
      const upper = iv.filter((i) => i !== 0);
      const four = upper.length > 4 ? upper.filter((i) => i !== fifth) : upper;
      out = closed(rootPc, four.length >= 3 ? four : [0, ...four], center);
      break;
    }
    case "power": { const r = rootPc + Math.round((center - 7 - rootPc) / 12) * 12; out = [r, r + 7, r + 12]; break; }
    case "stab": { const t = closed(rootPc, triad, center); out = [...t, t[0]! + 12]; break; }
    case "spread": {
      const r = rootPc + Math.round((center - 10 - rootPc) / 12) * 12;
      out = [r, r + fifth, r + third + 12, r + (seventh ?? 12) + 12];
      if (iv.includes(14) && settings.complexity > 0.62) out.push(r + 26);
      break;
    }
  }
  return [...new Set(out)].filter((p) => p >= 24 && p <= 100).sort((a, b) => a - b);
}

/** Bass register (C2…B2) for a chord root. */
const bassOf = (settings: KeysSettings, chord: Chord) => 36 + ((settings.tonic + chord.root) % 12);
function leftTone(settings: KeysSettings, chord: Chord, ch: string): number[] {
  const root = bassOf(settings, chord);
  const iv = chord.intervals;
  const third = iv.find((i) => i === 3 || i === 4) ?? iv.find((i) => i === 2 || i === 5) ?? 4;
  const fifth = iv.find((i) => i >= 6 && i <= 8) ?? 7;
  const seventh = iv.find((i) => i === 9 || i === 10 || i === 11) ?? 10;
  switch (ch) {
    case "3": return [root + third];
    case "5": return [root + fifth];
    case "6": return [root + 9];
    case "7": return [root + seventh];
    case "8": return [root + 12];
    case "c": return closed((settings.tonic + chord.root) % 12, [0, third, fifth], 55);
    default: return [root];
  }
}

// ---------------------------------------------------------------- bars

const clamp01 = (v: number) => Math.max(0, Math.min(1, Number.isFinite(v) ? v : 0));
const clampVel = (v: number) => Math.max(0.05, Math.min(1, v));

/** Picks base or busy character for a step (busy notes fade in with complexity). */
function lineChar(base: string, busy: string, s: number, cx: number, seed: number, phrase: number, hand: string): string {
  const i = s % 16;
  let ch = base[i] ?? ".";
  if (ch === "g" && cx < 0.45) ch = ".";
  if (ch === "o" && cx < 0.18) ch = ".";
  const y = busy[i] ?? ".";
  if (ch === "." && y !== "." && y !== "-") {
    const gate = (cx - 0.3) / 0.7;
    if (gate > 0 && rand01(seed, phrase, hand, s, "busy") < gate) ch = y;
  }
  return ch;
}

/** How long a hit at step s rings: held by "-", otherwise up to two steps (never past the bar). */
function holdLength(line: string, s: number, spb: number, sustained: boolean): number {
  let n = 1;
  while (s + n < spb && line[(s + n) % 16] === "-") n++;
  if (n > 1) return n;
  let gap = 1;
  while (s + gap < spb && (line[(s + gap) % 16] ?? ".") === ".") gap++;
  return Math.max(1, Math.min(sustained ? gap : 2, gap));
}

/**
 * Generates one bar of the keyboard part. `bar` is the bar number in the song (0-based) and
 * `stepsPerBar` follows the song's time signature (16 for 4/4).
 */
export function genKeysBar(settings: KeysSettings, bar: number, stepsPerBar = 16, opts: KeysBarOptions = {}): KeyNote[] {
  const style = keysStyleById(settings.style);
  const spb = Math.max(1, Math.round(stepsPerBar));
  if (opts.silent) return [];
  const cx = clamp01(settings.complexity);
  const loud = 0.42 + clamp01(settings.loudness) * 0.5;
  const human = clamp01(settings.humanize);
  const phrase = bar % 2;
  const sustained = !!soundById(settings.sound).sustained;
  const notes: KeyNote[] = [];
  const vel = (v: number, s: number, salt: string) => clampVel(v * loud + (rand01(settings.seed, bar, s, salt, "vel") - 0.5) * 0.16 * human);
  const fillLen = opts.fill ? Math.min(spb, clamp01(settings.fills) > 0.5 ? 8 : 4) : 0;
  const fillStart = spb - fillLen;
  const changeSteps = new Set<number>();
  for (let s = 1; s < spb; s++) if (chordAt(settings, bar, s, spb) !== chordAt(settings, bar, s - 1, spb)) changeSteps.add(s);

  /** Adds a note; a held note that runs into a chord change stops there and the new chord is struck. */
  const add = (hand: Hand, s: number, len: number, v: number, pitchesFor: (c: Chord) => number[]) => {
    let start = s, left = len;
    let strike = v;
    while (left > 0) {
      let run = 1;
      while (run < left && !changeSteps.has(start + run)) run++;
      for (const pitch of pitchesFor(chordAt(settings, bar, start, spb))) notes.push({ pitch, step: start, length: run, vel: strike, hand });
      start += run; left -= run; strike = clampVel(v * 0.85);
    }
  };

  // ---- right hand
  if (settings.hands.right !== false) {
    const [base = "", busy = ""] = style.right;
    let arp = 0;
    for (let s = 0; s < (opts.fill ? fillStart : spb); s++) {
      const ch = lineChar(base, busy, s, cx, settings.seed, phrase, "R");
      if (ch === "." || ch === "-") continue;
      const accent = VEL[ch] ?? 0.8;
      const len = holdLength(base[s % 16] === ch ? base : busy, s, spb, sustained);
      if (ch === "a") {
        const idx = arp++;
        add("R", s, len, vel(accent, s, "R"), (c) => {
          const tones = voiceChord(settings, c, style.voicing);
          const seq = [...tones, ...tones.map((t) => t + 12)];
          const cyc = Math.max(1, seq.length * 2 - 2);
          const j = idx % cyc;
          return [seq[j < seq.length ? j : cyc - j]!];
        });
      } else if (ch === "t") {
        add("R", s, len, vel(accent, s, "R"), (c) => [voiceChord(settings, c, style.voicing).at(-1)!]);
      } else {
        add("R", s, len, vel(accent * 0.86, s, "R"), (c) => voiceChord(settings, c, style.voicing));
      }
    }
    if (opts.fill && fillLen) notes.push(...fillNotes(settings, style, bar, spb, fillStart, loud));
    if (opts.hit) {
      for (let i = notes.length - 1; i >= 0; i--) if (notes[i]!.hand === "R" && notes[i]!.step === 0) notes.splice(i, 1);
      const len = Math.min(spb, sustained ? spb / 2 : 4);
      add("R", 0, len, clampVel(loud * 1.05), (c) => voiceChord(settings, c, style.voicing));
    }
  }

  // ---- left hand
  if (settings.hands.left !== false) {
    if (style.left === "walk") notes.push(...walkBar(settings, bar, spb, cx, loud, human));
    else {
      const [base = "", busy = ""] = style.left;
      for (let s = 0; s < spb; s++) {
        const ch = lineChar(base, busy, s, cx, settings.seed, phrase, "L");
        if (ch === "." || ch === "-") continue;
        const accent = LEFT_VEL[ch] ?? 0.8;
        const len = holdLength(base[s % 16] === ch ? base : busy, s, spb, sustained);
        add("L", s, len, vel(accent * 0.92, s, "L"), (c) => leftTone(settings, c, ch));
      }
    }
    if (opts.hit && !notes.some((n) => n.hand === "L" && n.step === 0)) add("L", 0, Math.min(spb, 4), clampVel(loud), (c) => [bassOf(settings, c)]);
  }

  // One note per pitch and step (the loudest), so a fill or hit over the comping never doubles a key.
  const best = new Map<string, KeyNote>();
  for (const n of notes) {
    const key = `${n.pitch}:${n.step}`;
    const prev = best.get(key);
    if (!prev || n.vel > prev.vel) best.set(key, prev ? { ...n, length: Math.max(n.length, prev.length) } : n);
  }
  return [...best.values()].sort((a, b) => a.step - b.step || a.pitch - b.pitch);
}

/** Walking bass: a note on every beat — roots on chord changes, chord tones between, a chromatic step into the next chord. */
function walkBar(settings: KeysSettings, bar: number, spb: number, cx: number, loud: number, human: number): KeyNote[] {
  const out: KeyNote[] = [];
  const beats = Math.max(1, Math.floor(spb / 4));
  for (let b = 0; b < beats; b++) {
    const s = b * 4;
    const c = chordAt(settings, bar, s, spb);
    const startsChord = b === 0 || chordAt(settings, bar, s - 1, spb) !== c;
    const nextC = s + 4 < spb ? chordAt(settings, bar, s + 4, spb) : chordAt(settings, bar + 1, 0, spb);
    const root = bassOf(settings, c);
    let pitch: number;
    const r = rand01(settings.seed, bar, b, "walk");
    if (startsChord) pitch = root;
    else if (nextC !== c || b === beats - 1) {
      const target = bassOf(settings, nextC);
      pitch = target + (r < 0.5 ? -1 : 1);
    } else {
      const iv = c.intervals;
      const third = iv.find((i) => i === 3 || i === 4) ?? 4;
      const fifth = iv.find((i) => i >= 6 && i <= 8) ?? 7;
      pitch = root + (r < 0.4 ? third : r < 0.8 ? fifth : 12);
    }
    while (pitch > 52) pitch -= 12;
    while (pitch < 33) pitch += 12;
    const v = clampVel((b % 2 === 0 ? 0.86 : 0.76) * loud + (rand01(settings.seed, bar, b, "wv") - 0.5) * 0.14 * human);
    out.push({ pitch, step: s, length: 4, vel: v, hand: "L" });
    // the occasional skip note on the "a" of the beat when playing busy
    if (cx > 0.72 && b < beats - 1 && rand01(settings.seed, bar, b, "skip") < (cx - 0.72) * 1.6) out.push({ pitch, step: s + 3, length: 1, vel: clampVel(v * 0.5), hand: "L" });
  }
  return out;
}

const MAJOR_SCALE = [0, 2, 4, 5, 7, 9, 11];
const MINOR_SCALE = [0, 2, 3, 5, 7, 8, 10];

function fillNotes(settings: KeysSettings, style: KeysStyle, bar: number, spb: number, start: number, loud: number): KeyNote[] {
  const out: KeyNote[] = [];
  const len = spb - start;
  const dense = clamp01(settings.fills) > 0.6;
  const chord = chordAt(settings, bar, start, spb);
  const tones = voiceChord(settings, chord, style.voicing);
  const rise = (k: number, n: number) => clampVel((0.55 + 0.45 * (k / Math.max(1, n - 1))) * loud);
  switch (style.fill) {
    case "run":
    case "cascade": {
      const seq = [...tones, ...tones.map((t) => t + 12), ...tones.map((t) => t + 24)];
      const up = style.fill === "run";
      const stride = dense ? 1 : 2;
      const count = Math.ceil(len / stride);
      for (let k = 0; k < count; k++) {
        // runs climb from the chord; cascades fall from an octave above it
        const i = up ? k : seq.length - 1 - tones.length - k;
        const p = seq[Math.max(0, Math.min(seq.length - 1, i))]!;
        out.push({ pitch: p, step: start + k * stride, length: k === count - 1 ? Math.max(1, spb - (start + k * stride)) : stride, vel: rise(k, count), hand: "R" });
      }
      break;
    }
    case "stabs": {
      const stride = dense ? 1 : 2;
      for (let s = start, k = 0; s < spb; s += stride, k++) for (const p of tones) out.push({ pitch: p, step: s, length: 1, vel: rise(k, len / stride), hand: "R" });
      break;
    }
    case "gliss": {
      // a quick sweep up the scale, three notes per 16th, landing on the chord
      const minor = chord.intervals.includes(3) && !chord.intervals.includes(4);
      const scale = minor ? MINOR_SCALE : MAJOR_SCALE;
      const rootPc = (settings.tonic + chord.root) % 12;
      const span = Math.min(len, dense ? 4 : 2);
      const begin = spb - span;
      const per = 3;
      const total = span * per;
      // walk down the scale from the chord's top note, then play it upwards so the sweep lands there
      const sweep: number[] = [];
      for (let p = tones[tones.length - 1]!; sweep.length < total && p > 24; p--) if (scale.includes((((p - rootPc) % 12) + 12) % 12)) sweep.push(p);
      if (begin > start) for (const p of tones) out.push({ pitch: p, step: start, length: begin - start, vel: rise(0, 2), hand: "R" });
      sweep.reverse().forEach((pitch, k) => out.push({ pitch, step: begin + k / per, length: 0.34, vel: rise(k, total) * 0.8, hand: "R" }));
      break;
    }
    case "turn": {
      // the dominant of the next chord, struck on the "a" of the beats leading in
      const next = chordAt(settings, bar + 1, 0, spb);
      const dom: Chord = { root: (next.root + 7) % 12, intervals: [0, 4, 7, 10, 13], symbol: "V7b9", quality: "7♭9" };
      const domTones = voiceChord(settings, dom, style.voicing === "power" ? "triad" : style.voicing);
      const half = start + Math.floor(len / 2);
      for (let s = start; s < spb; s++) {
        const into = s - start;
        if (into % 4 !== 3 && !(dense && into % 4 === 1) && s !== start) continue;
        const use = s >= half ? domTones : tones;
        for (const p of use) out.push({ pitch: p, step: s, length: 1, vel: rise(into, len), hand: "R" });
      }
      break;
    }
  }
  return out;
}

/** The part for `count` bars starting at song bar `startBar`, with its usual fills and big chords. */
export function keysBars(settings: KeysSettings, startBar: number, count: number, stepsPerBar: number) {
  return Array.from({ length: Math.max(1, count) }, (_, i) => ({ bar: startBar + i, notes: genKeysBar(settings, i, stepsPerBar, keysBarOptions(settings, i)) }));
}

/**
 * Turns played/printed bars into piano-roll notes at their song positions. The notes end at
 * the printed range (recordedEnd), so the part sits on its bars instead of looping across the song.
 */
export function keysToNotes(bars: { bar: number; notes: KeyNote[] }[], stepsPerBar: number) {
  const spb = Math.max(1, Math.round(stepsPerBar));
  const last = bars.reduce((m, b) => Math.max(m, b.bar), 0);
  const total = (last + 1) * spb;
  const notes = bars.flatMap(({ bar, notes: ns }) => ns.map((n) => ({
    step: bar * spb + n.step, length: n.length, pitch: n.pitch, velocity: Math.round(n.vel * 100) / 100, recordedEnd: total,
  })));
  return { notes, steps: total };
}
